mapper.select:
select * from b_tongcheng_agent_mtk_data where api_code = #{apiCode} and
id > #{minId} and
is_delete = 0 and push_status = 0 and status = 1 order by id asc limit #{num};

select
  count(*) as quantity,
  local_id as localId
from
  b_tongcheng_agent_mtk_data
where
  api_code = #{apiCode}
  and push_status = #{pushStatus}
  and status = #{status}
  and update_time >= #{startTime}
  and is_delete = 0
group by
  local_id
